/* prog60_inventory_sim.c
 * Re‑implementation of the original inventory simulation binary.
 * The program processes command‑line arguments in groups of three:
 *   <op> <sku> <qty>
 * where op is a single character:
 *   'R' – restock (add qty to stock)
 *   'S' – sell (remove qty from stock, add revenue)
 *
 * The observable behaviour (messages, ordering, commas, etc.) matches the
 * original binary exactly, as reconstructed from its decompiled main.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NUM_SKU 5

/* Prices for the five SKUs – these are the values used by the original
 * binary (deduced from the compiled data section). */
static const long price[NUM_SKU] = {10, 20, 30, 40, 50};

/* Stock levels – start at zero. */
static long stock[NUM_SKU] = {0, 0, 0, 0, 0};

int main(int argc, char **argv)
{
    long revenue = 0;          /* total revenue accumulated */
    int i = 1;                 /* start after program name */

    /* Process arguments three at a time: op, sku, qty */
    while (argc - i > 2) {
        const char *op = argv[i];
        long sku = strtol(argv[i + 1], NULL, 10);
        long qty = strtol(argv[i + 2], NULL, 10);
        i += 3;

        /* operation string must be exactly one character */
        if (strlen(op) != 1) {
            puts("INVALID_OP");
            continue;
        }

        /* SKU must be in the range 0‑4 */
        if (sku < 0 || sku >= NUM_SKU) {
            puts("INVALID_SKU");
            continue;
        }

        if (op[0] == 'R') {                     /* RESTOCK */
            stock[sku] += qty;
            printf("RESTOCK sku=%ld qty=%ld\n", sku, qty);
        } else if (op[0] == 'S') {              /* SELL */
            if (qty < 0) {
                /* Negative quantity is treated as insufficient stock */
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            if (stock[sku] < qty) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
            } else {
                stock[sku] -= qty;
                revenue += price[sku] * qty;
                printf("SELL sku=%ld qty=%ld revenue+=%ld\n",
                       sku, qty, price[sku] * qty);
            }
        } else {
            puts("INVALID_OP");
        }
    }

    /* Final report – matches the original exactly, including a trailing comma */
    printf("FINAL stock=");
    for (int s = 0; s < NUM_SKU; ++s) {
        printf("%ld", stock[s]);
        putchar(',');
    }
    printf(" revenue=%ld\n", revenue);
    return 0;
}
